'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var isArray = require( '@stdlib/assert/is-array' );
var Axis = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Axis, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `properties` property', function test( t ) {
	var v;

	v = new Axis({
		'scale': 'xScale',
		'orient': 'bottom'
	});
	t.strictEqual( hasOwnProp( v, 'properties' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'properties' ), true, 'returns expected value' );
	t.strictEqual( isArray( v.properties ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `properties` property which returns a list of enumerable properties', function test( t ) {
	var expected;
	var props;
	var axis;

	axis = new Axis({
		'scale': 'xScale',
		'orient': 'bottom'
	});
	props = axis.properties;

	t.strictEqual( isArray( props ), true, 'returns expected value' );

	expected = [
		'aria',
		'bandPosition',
		'description',
		'domain',
		'domainCap',
		'domainColor',
		'domainDash',
		'domainDashOffset',
		'domainOpacity',
		'domainWidth',
		'encode',
		'format',
		'formatType',
		'grid',
		'gridCap',
		'gridColor',
		'gridDash',
		'gridDashOffset',
		'gridOpacity',
		'gridScale',
		'gridWidth',
		'labelAlign',
		'labelAngle',
		'labelBaseline',
		'labelBound',
		'labelColor',
		'labelFlush',
		'labelFlushOffset',
		'labelFont',
		'labelFontSize',
		'labelFontStyle',
		'labelFontWeight',
		'labelLimit',
		'labelLineHeight',
		'labelOffset',
		'labelOpacity',
		'labelOverlap',
		'labelPadding',
		'labels',
		'labelSeparation',
		'maxExtent',
		'minExtent',
		'offset',
		'orient',
		'position',
		'scale',
		'tickBand',
		'tickCap',
		'tickColor',
		'tickCount',
		'tickDash',
		'tickDashOffset',
		'tickExtra',
		'tickMinStep',
		'tickOffset',
		'tickOpacity',
		'tickRound',
		'ticks',
		'tickSize',
		'tickWidth',
		'title',
		'titleAlign',
		'titleAnchor',
		'titleAngle',
		'titleBaseline',
		'titleColor',
		'titleFont',
		'titleFontSize',
		'titleFontStyle',
		'titleFontWeight',
		'titleLimit',
		'titleLineHeight',
		'titleOpacity',
		'titlePadding',
		'titleX',
		'titleY',
		'translate',
		'values',
		'zindex'
	];
	t.deepEqual( props, expected, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `properties` property which returns a new array on each access', function test( t ) {
	var props1;
	var props2;
	var axis;

	axis = new Axis({
		'scale': 'xScale',
		'orient': 'bottom'
	});
	props1 = axis.properties;
	props2 = axis.properties;

	t.notEqual( props1, props2, 'returns expected value' );
	t.deepEqual( props1, props2, 'returns expected value' );

	t.end();
});
